WITH filtered_transactions AS (SELECT *, CASE WHEN is_flagged THEN 'Yes' ELSE 'No' END AS is_flagged_label FROM transactions WHERE is_flagged AND merchant <> 'Shell' AND merchant = 'Shell'), summary AS (SELECT merchant, HOUR(txn_time) AS txn_hour, ROUND(AVG(amount), 2) AS avg_amount FROM filtered_transactions GROUP BY merchant, HOUR(txn_time)) SELECT merchant, txn_hour FROM summary WHERE avg_amount > 33 ORDER BY merchant ASC, txn_hour ASC LIMIT 5
